  id UUID PRIMARY KEY, plate TEXT NOT NULL, vehicle TEXT NOT NULL,
  spot_id TEXT NOT NULL REFERENCES spots(id), entry_at TIMESTAMPTZ NOT NULL,
  status TEXT NOT NULL, replaces UUID NULL, penalty_minor BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE payments (
  payment_id TEXT PRIMARY KEY, ticket_id UUID NOT NULL REFERENCES tickets(id),
  amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), at TIMESTAMPTZ NOT NULL
);

